{
  "meetingType": "team_sync",
  "overview": null,
  "sections": [
    {
      "title": {
        "text": "Logistics and Site Preparation",
        "sources": [
          "R1",
          "R10",
          "R15"
        ]
      },
      "items": [
        {
          "text": "The gallery inspection confirmed the loading door is wide enough for the largest crate and the lift is functional.",
          "sources": [
            "R1"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "The entrance includes a bench beside the coat hooks; the room felt welcoming during the trial.",
          "sources": [
            "R10"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "The floor plan shows the bench and both exits; photographs made the entrance look narrower than it is, but the measured inspection is complete.",
          "sources": [
            "R15"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    },
    {
      "title": {
        "text": "Artwork and Documentation",
        "sources": [
          "R0",
          "R7",
          "R8",
          "R9"
        ]
      },
      "items": [
        {
          "text": "Priya will book the artwork courier by Thursday once the insurance certificate is approved.",
          "sources": [
            "R0"
          ],
          "kind": "action",
          "owner": "Priya",
          "due": "Thursday"
        },
        {
          "text": "The print estimate for a large catalogue exceeds the budget; a hundred copies will be printed with a QR link for additional readers.",
          "sources": [
            "R7",
            "R8"
          ],
          "kind": "decision",
          "owner": null,
          "due": null
        },
        {
          "text": "The catalogue PDF and QR link already exist and were tested on both phones.",
          "sources": [
            "R9"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    },
    {
      "title": {
        "text": "Visitor Experience and Content",
        "sources": [
          "R2",
          "R4",
          "R5",
          "R6",
          "R11",
          "R16",
          "R17"
        ]
      },
      "items": [
        {
          "text": "Lena was relieved by the lift result as it avoided the need to carry pieces up stairs; she noted the lighting was softer in the afternoon.",
          "sources": [
            "R2"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "Omar offered to record a narrated audio tour describing materials; the offer remains unaccepted and is not a current task.",
          "sources": [
            "R4",
            "R16"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "Trial observations showed visitors liked space to look without commentary; these do not represent a definitive survey of all visitor preferences.",
          "sources": [
            "R5"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "Artists provided varying descriptions (tools vs. memories); the notes should preserve this variety rather than a single interpretation.",
          "sources": [
            "R6"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "Artists expressed a range of feelings (pride and uncertainty) regarding their work; this is not evidence of any withdrawal.",
          "sources": [
            "R11"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "The preview was encouraging as visitors noticed details the artists hadn't expected; this is distinct from the future public opening.",
          "sources": [
            "R17"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    },
    {
      "title": {
        "text": "Internal Coordination",
        "sources": [
          "R3",
          "R12",
          "R13",
          "R14",
          "R18",
          "R19"
        ]
      },
      "items": [
        {
          "text": "Priya will send the existing floor plan to Lena by Thursday for use in visitor conversations.",
          "sources": [
            "R18"
          ],
          "kind": "action",
          "owner": "Priya",
          "due": "Thursday"
        },
        {
          "text": "Priya's previous commitment to replace the camera equipment list is withdrawn as the folder already contains the corrected list.",
          "sources": [
            "R12",
            "R13"
          ],
          "kind": "decision",
          "owner": null,
          "due": null
        },
        {
          "text": "The installation photographs are not a floor plan; the actual floor plan should be used to discuss layout with visitors.",
          "sources": [
            "R14"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    }
  ],
  "recentWin": {
    "win": {
      "text": "The gallery inspection confirmed the loading door is wide enough for the largest crate, and the lift worked during the visit.",
      "sources": [
        "R1"
      ]
    },
    "impact": {
      "text": "This confirmed the route from the street and ensured the physical feasibility of moving the artwork.",
